function validate([items1, items2]) {
  for (const [name, items] of [['items1', items1], ['items2', items2]]) {
    if (!Array.isArray(items) || items.length < 1 || items.length > 1000) return `${name} needs 1 to 1000 items.`;
    const seen = new Set();
    for (const item of items) {
      if (!Array.isArray(item) || item.length !== 2) return `Each item in ${name} is a [value, weight] pair.`;
      const [value, weight] = item;
      if (!Number.isInteger(value) || value < 1 || value > 1000) return 'Each value is an integer from 1 to 1000.';
      if (!Number.isInteger(weight) || weight < 1 || weight > 1000) return 'Each weight is an integer from 1 to 1000.';
      if (seen.has(value)) return `The values in ${name} must be distinct.`;
      seen.add(value);
    }
  }
  return null;
}

