function generate(rand, size) {
  const pick = (pool, count) => {
    const copy = pool.slice();
    for (let i = copy.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [copy[i], copy[j]] = [copy[j], copy[i]]; }
    return copy.slice(0, count);
  };
  const span = size === 'large' ? 1000 : 2 + Math.floor(rand() * 8);
  const pool = Array.from({ length: span }, (_, i) => i + 1);
  const maxWeight = size === 'large' ? 1000 : (rand() < 0.5 ? 5 : 1000);
  const build = () => {
    const n = size === 'large' ? 500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * span);
    return pick(pool, n).map(value => [value, 1 + Math.floor(rand() * maxWeight)]);
  };
  return [build(), build()];
}
